<?php if(!$setupError): ?><script>
(function(){
const api='ivr_api.php', csrf=<?=json_encode($_SESSION['csrf_token'])?>, sessions=document.getElementById('ivr-call-sessions'), historyBody=document.getElementById('ivr-history');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
async function request(action,data,upload){let opts={method:data?'POST':'GET',credentials:'same-origin'};let url=api+'?action='+encodeURIComponent(action);if(data){if(upload){opts.body=data;}else{data.append('_csrf',csrf);opts.headers={'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'};opts.body=new URLSearchParams(data).toString();}}let res=await fetch(url,opts),json=await res.json();if(!res.ok||!json.ok)throw new Error(json.error||'Request failed');return json;}
async function getCall(id){let res=await fetch(api+'?action=call&call_id='+encodeURIComponent(id),{credentials:'same-origin'}),json=await res.json();if(!res.ok||!json.ok)throw new Error(json.error||'Call lookup failed');return json;}
function toast(msg,error){let box=document.getElementById('ivr-toast');if(!box){box=document.createElement('div');box.id='ivr-toast';box.className='alert';document.querySelector('.mcare-ivr-page').prepend(box);}box.className='alert '+(error?'alert-danger':'alert-success');box.textContent=msg;window.setTimeout(()=>box.remove(),5000);}
function callCard(c){let options=c.call_source==='web_simulator'?(c.options||[]).map(o=>`<button class="btn btn-default btn-sm ivr-key" data-call="${esc(c.call_id)}" data-digit="${esc(o.digit)}"><kbd>${esc(o.digit)}</kbd> ${esc(o.option_label)}</button>`).join(''):(c.options||[]).map(o=>`<span class="label label-default"><kbd>${esc(o.digit)}</kbd> ${esc(o.option_label)}</span>`).join('');let message=c.last_event&&c.last_event.message?`<div class="ivr-call-message">${esc(c.last_event.message).replace(/\n/g,'<br>')}</div>`:'';let audio=c.audio_path?`<audio controls preload="none" src="${esc(c.audio_path)}"></audio>`:'';let end=c.call_source!=='web_simulator'||['completed','failed'].includes(c.status)?'':`<button class="btn btn-danger btn-xs ivr-end" data-call="${esc(c.call_id)}">End call</button>`;let speak=c.call_source==='web_simulator'?`<button class="btn btn-link btn-xs ivr-speak" data-language="${esc(c.language||'en')}" data-prompt="${esc(c.prompt||'')}">Browser voice preview</button>`:'';let source=c.call_source==='asterisk_local'?'LOCAL SIP TEST':'BROWSER SIMULATION';let events=(c.events||[]).map(ev=>`<li><time>${esc(ev.created_at)}</time> · <strong>${esc(ev.type)}</strong> · ${esc(ev.menu||'')} ${esc(ev.value||'')} ${ev.message?`<p>${esc(ev.message)}</p>`:''}</li>`).join('');let error=c.error_message?`<div class="alert alert-danger">${esc(c.error_message)}</div>`:'';return `<article class="ivr-call-card ${['completed','failed'].includes(c.status)?'is-ended':''}" data-call-card="${esc(c.call_id)}"><header><div><span class="ivr-test-tag">TEST · ${source}</span> <strong>${esc(c.caller_number)}</strong><small>${esc(c.call_uuid)}</small></div><span class="ivr-state">${esc(c.status)} · ${esc(c.state)}</span></header><div class="ivr-call-meta"><span>Caller fixture: ${esc(c.fixture)}</span><span>Language: ${esc(c.language||'choose below')}</span><span>Started: ${esc(c.started_at)}</span></div><div class="ivr-prompt"><strong>Prompt</strong><p>${esc(c.prompt||'Welcome language prompt is bilingual.')}</p>${audio}</div>${message}${error}<div class="ivr-keypad">${options||'<span class="text-muted">No keypad choices in this state.</span>'}</div><details class="ivr-call-events"><summary>Call details · ${events?c.events.length:0} recent events</summary><ol>${events||'<li>No call events recorded.</li>'}</ol></details><footer>${speak} ${end}</footer></article>`;}
async function refreshCalls(){let data=await request('list');let active=data.calls.filter(c=>['active','queued','answered_simulated'].includes(c.status));document.getElementById('ivr-active-count').textContent=active.length+' active';let voiceSelect=document.getElementById('ivr-speech-call'),selectedVoice=voiceSelect.value;voiceSelect.innerHTML='<option value="">Speech sample only</option>'+active.filter(c=>c.language==='rw').map(c=>`<option value="${esc(c.ivr_call_id)}">${esc(c.caller_number)} · #${esc(c.ivr_call_id)}</option>`).join('');if(active.some(c=>String(c.ivr_call_id)===selectedVoice))voiceSelect.value=selectedVoice;if(!data.calls.length){sessions.innerHTML='<div class="ivr-empty">No test calls yet. Start a simulated call above.</div>';return;}let calls=await Promise.all(active.slice(0,30).map(c=>getCall(c.ivr_call_id)));let activeIds=new Set(calls.map(x=>String(x.call.call_id)));let terminal=data.calls.filter(c=>!activeIds.has(String(c.ivr_call_id))).slice(0,4);let terminalCalls=await Promise.all(terminal.map(c=>getCall(c.ivr_call_id)));sessions.innerHTML=[...calls.map(x=>callCard(x.call)),...terminalCalls.map(x=>callCard(x.call))].join('')||'<div class="ivr-empty">No test calls yet.</div>';renderHistory(data.calls);}
function renderHistory(calls){historyBody.innerHTML=calls.slice(0,50).map(c=>`<tr><td title="${esc(c.call_uuid)}">#${esc(c.ivr_call_id)}</td><td>${c.call_source==='asterisk_local'?'Local SIP':'Browser sim.'}</td><td>${esc(c.caller_number)}</td><td>${esc(c.language||'—')}</td><td>${esc(c.state)}</td><td><span class="label ${c.status==='completed'?'label-success':c.status==='failed'?'label-danger':'label-info'}">${esc(c.status)}</span></td><td>${esc(c.started_at)}</td><td>${esc(c.duration_seconds??'—')}</td><td>${esc(c.last_message||'—')}</td></tr>`).join('')||'<tr><td colspan="9" class="text-muted">No test calls.</td></tr>';}
async function refreshQueue(){let data=await request('queue'),box=document.getElementById('ivr-queue');if(!data.queue.length){box.innerHTML='<p class="text-muted">No callers are waiting.</p>';return;}box.innerHTML='<div class="table-responsive"><table class="table"><thead><tr><th>TEST caller</th><th>Language</th><th>Wait (sec)</th><th>Simulated action</th></tr></thead><tbody>'+data.queue.map(q=>`<tr><td>${esc(q.caller_number)}<br><small>${esc(q.caller_fixture)}</small></td><td>${esc(q.language)}</td><td>${esc(q.wait_seconds)}</td><td><button class="btn btn-success btn-xs ivr-queue-action" data-call="${esc(q.ivr_call_id)}" data-decision="answer">Simulate answer</button> <button class="btn btn-warning btn-xs ivr-queue-action" data-call="${esc(q.ivr_call_id)}" data-decision="reject">Simulate unavailable</button></td></tr>`).join('')+'</tbody></table></div>';}
async function refreshStats(){let d=await request('stats'),s=d.stats||{};for(let key of ['total_calls','active_calls','completed_calls','failed_calls','avg_duration','concurrent_calls'])document.querySelector(`[data-stat="${key}"]`).textContent=s[key]??0;document.getElementById('ivr-avg-wait').textContent=(s.avg_wait??0)+' sec';document.getElementById('ivr-escalations').textContent=d.test_escalations;document.getElementById('ivr-transfers').textContent=d.simulated_transfers;document.getElementById('ivr-capacity').textContent=s.concurrent_calls+' / '+d.capacity;document.getElementById('ivr-languages').textContent=(d.by_language||[]).map(x=>x.language+': '+x.total).join(' · ')||'No calls';document.getElementById('ivr-menus').textContent=(d.by_menu||[]).map(x=>x.menu_key+': '+x.total).join(' · ')||'No menu selections';}
async function loadSettings(){let d=await request('settings');document.getElementById('ivr-max-calls').value=d.config.max_concurrent_calls;document.querySelector('#ivr-config-form [name="speech_test_enabled"]').checked=d.config.speech_test_enabled;document.getElementById('ivr-prompt-settings').innerHTML=d.prompts.map(p=>`<details class="ivr-config-item"><summary>${esc(p.prompt_key)} · ${esc(p.language.toUpperCase())}</summary><form class="ivr-prompt-form"><input type="hidden" name="_csrf" value="${esc(csrf)}"><input type="hidden" name="action" value="save_prompt"><input type="hidden" name="prompt_id" value="${esc(p.prompt_id)}"><textarea name="prompt_text" class="form-control" maxlength="1500" required>${esc(p.prompt_text)}</textarea><button class="btn btn-primary btn-xs" type="submit">Save text</button></form><form class="ivr-audio-form" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="${esc(csrf)}"><input type="hidden" name="action" value="upload_prompt"><input type="hidden" name="prompt_id" value="${esc(p.prompt_id)}"><input type="file" name="audio" accept="audio/wav,audio/mpeg,audio/ogg,audio/webm" required><button class="btn btn-default btn-xs" type="submit">Upload prompt audio</button>${p.audio_path?`<audio controls preload="none" src="${esc(p.audio_path)}"></audio>`:''}</form></details>`).join('');document.getElementById('ivr-menu-settings').innerHTML=d.menus.map(m=>`<form class="ivr-menu-form"><input type="hidden" name="_csrf" value="${esc(csrf)}"><input type="hidden" name="action" value="save_menu"><input type="hidden" name="option_id" value="${esc(m.option_id)}"><span class="ivr-menu-ident">${esc(m.menu_key)} · ${esc(m.language)} · <kbd>${esc(m.digit)}</kbd></span><input class="form-control" name="option_label" value="${esc(m.option_label)}" maxlength="180"><span class="ivr-action-name">${esc(m.action_key)}</span><label><input type="checkbox" name="is_active" value="1" ${m.is_active==1?'checked':''}> Enabled</label><button type="submit" class="btn btn-default btn-xs">Save</button></form>`).join('');}
document.getElementById('ivr-start-form').addEventListener('submit',async e=>{e.preventDefault();try{let d=await request('start',new FormData(e.currentTarget));// keep the default number; append a suffix only when it looks like a TEST- id
let cur=document.getElementById('ivr-caller');if(cur.value.startsWith('TEST-'))cur.value='TEST-25070000000'+(Math.floor(Math.random()*8)+2);toast('New independent TEST CALL started.');await refreshAll();}catch(err){toast(err.message,true);}});
sessions.addEventListener('click',async e=>{let key=e.target.closest('.ivr-key'),end=e.target.closest('.ivr-end'),speak=e.target.closest('.ivr-speak');try{if(key){let form=new URLSearchParams({_csrf:csrf,call_id:key.dataset.call,digit:key.dataset.digit});await request('step',form);await refreshAll();}else if(end){await request('end',new URLSearchParams({_csrf:csrf,call_id:end.dataset.call}));await refreshAll();}else if(speak){if(!('speechSynthesis'in window)){toast('Browser voice preview is unavailable. Use keypad prompts or upload audio.',true);return;}let voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith(speak.dataset.language==='rw'?'rw':'en'));if(speak.dataset.language==='rw'&&!voice){toast('This browser has no Kinyarwanda voice. Use keypad prompts; no Kinyarwanda speech synthesis is claimed.',true);return;}let utterance=new SpeechSynthesisUtterance(speak.dataset.prompt);utterance.lang=speak.dataset.language==='rw'?'rw-RW':'en-US';if(voice)utterance.voice=voice;speechSynthesis.speak(utterance);}}catch(err){toast(err.message,true);}});
document.getElementById('ivr-queue').addEventListener('click',async e=>{let b=e.target.closest('.ivr-queue-action');if(!b)return;try{let f=new URLSearchParams({_csrf:csrf,call_id:b.dataset.call,decision:b.dataset.decision});let d=await request('queue_resolve',f);toast(d.message);await refreshAll();}catch(err){toast(err.message,true);}});
document.getElementById('ivr-config-form').addEventListener('submit',async e=>{e.preventDefault();let f=new FormData(e.currentTarget);f.set('speech_test_enabled',e.currentTarget.querySelector('[name="speech_test_enabled"]').checked?'1':'0');try{let d=await request('save_config',f);toast(d.message);await refreshStats();}catch(err){toast(err.message,true);}});
document.getElementById('ivr-prompt-settings').addEventListener('submit',async e=>{if(e.target.matches('.ivr-prompt-form')){e.preventDefault();try{let d=await request('save_prompt',new FormData(e.target));toast(d.message);}catch(err){toast(err.message,true);}}else if(e.target.matches('.ivr-audio-form')){e.preventDefault();try{let d=await request('upload_prompt',new FormData(e.target),true);toast(d.message);await loadSettings();}catch(err){toast(err.message,true);}}});
document.getElementById('ivr-menu-settings').addEventListener('submit',async e=>{if(!e.target.matches('.ivr-menu-form'))return;e.preventDefault();let f=new FormData(e.target);f.set('is_active',e.target.querySelector('[name="is_active"]').checked?'1':'0');try{let d=await request('save_menu',f);toast(d.message);}catch(err){toast(err.message,true);}});
document.getElementById('ivr-speech-form').addEventListener('submit',async e=>{e.preventDefault();let box=document.getElementById('ivr-speech-result');box.textContent='Sending sample to the local Kinyarwanda ASR service…';try{let d=await request('speech_test',new FormData(e.currentTarget),true);let suggest=d.suggested_digit&&d.call_id?`<button type="button" class="btn btn-info btn-sm ivr-voice-suggestion" data-call="${esc(d.call_id)}" data-digit="${esc(d.suggested_digit)}">Review suggestion and choose keypad option ${esc(d.suggested_digit)}</button>`:'';box.innerHTML='<p><strong>Draft transcript (review required):</strong> '+esc(d.transcript)+'</p><p>'+esc(d.message)+'</p>'+suggest+(d.intent_analysis?'<pre>'+esc(JSON.stringify(d.intent_analysis,null,2))+'</pre>':'<p class="text-muted">Optional intent service is not configured; voice remains a transcription-only test.</p>');}catch(err){box.textContent=err.message;}});
document.getElementById('ivr-speech-result').addEventListener('click',async e=>{let b=e.target.closest('.ivr-voice-suggestion');if(!b)return;try{await request('step',new URLSearchParams({_csrf:csrf,call_id:b.dataset.call,digit:b.dataset.digit}));toast('Confirmed keypad choice submitted for the selected test call.');await refreshAll();}catch(err){toast(err.message,true);}});
document.getElementById('ivr-refresh-history').addEventListener('click',()=>refreshAll().catch(err=>toast(err.message,true)));
async function refreshAll(){await Promise.all([refreshCalls(),refreshQueue(),refreshStats()]);}
loadSettings().catch(err=>toast(err.message,true));refreshAll().catch(err=>toast(err.message,true));window.setInterval(()=>refreshAll().catch(()=>{}),4000);
})();
</script><?php endif; ?>
